  "as.ex.stated": "Reviewed field is stated; no configured explicit concern matched. This does not verify the claim or establish fairness.",
  "as.ex.missing": "No reviewed evidence for this criterion. Missing information is not evidence of wrongdoing.",
  "as.ex.uncertain": "This value is unresolved or outside the rule's supported format; no points awarded until clarified.",
  "as.ex.concern": "The reviewed field explicitly states an obligation requiring attention. This is an advisory concern, not a finding of illegality.",
  "as.meaning": "Points supported by 20 equally weighted clarity and protection checks (5 each). Higher means more reviewed terms stated without a configured explicit concern, not a safer employer or a fair market wage.",
  "as.limitations": "Product checklist, not an empirically validated rating, legal opinion, salary benchmark or safety guarantee. Claims may be inaccurate. Rules can miss risks and contradictions. Employer legitimacy, independent verification and AI observations are excluded. No jurisdiction-specific legal thresholds are applied.",
