  "add.pasteNote": "පෙළ මෙම තිරයේ පමණක් පවතී. විකල්ප ස්ථානීය රීති ඔබේ සමාලෝචනය සඳහා ක්ෂේත්‍ර යෝජනා කරයි; ඒවා AI භාවිත නොකරන අතර බාහිර සේවාවක් අමතන්නේ නැත.",
  "add.suggest": "ස්ථානීය රීති මගින් කොන්දේසි යෝජනා කරන්න",
