  "add.nothingFilled": "නව ක්ෂේත්‍ර කිසිවක් පුරවා නැත.",
  "add.preserved": "පවතින ක්ෂේත්‍ර {count} ක් තබාගන්නා ලදී; ආදේශක යෝජනාවක් ඉල්ලීමට පෙර ක්ෂේත්‍රයක් හිස් කරන්න.",
  "add.noneDetected": "සහාය දක්වන, පැහැදිලි කොන්දේසි කිසිවක් හඳුනාගත නොහැකි විය. දීමනා විස්තර පහතින් අතින් ඇතුළත් කරන්න.",
  "add.reviewEvery": "සුරැකීමට පෙර පහත සෑම ක්ෂේත්‍රයක්ම සමාලෝචනය කරන්න; රීති මගින් මුදල් සහ සන්දර්භය වැරදි ලෙස අර්ථ දැක්විය හැක.",
