  "add.workerNote": "ඔබේ සේවක ගිණුම ඔබ පිවිසී ඇති පැතිකඩෙන් ගනු ලැබේ.",
  "add.employerNote": "සේවකයාගෙන් ඔහුගේ ගිණුම් හැඳුනුම්පත විමසන්න. තෝරාගත් සංවිධානය සඳහා ඔබට වත්මන් ස්වාධීන අධිකාරියක් තිබිය යුතු අතර, දෙපාර්ශ්වයක් ලෙසම තහවුරු කළ නොහැක.",
