  "add.analyzeNote": "‘දීමනාව විශ්ලේෂණය කරන්න’ සමාලෝචනය කළ ක්ෂේත්‍ර සුරකින අතර අඩු කොන්දේසි පරීක්ෂා කරයි. අලවන ලද පෙළ ස්වයංක්‍රීයව කොන්දේසි ලෙස සුරකින්නේ නැත; ස්ථානීය යෝජනා භාවිත කර මුලින් ක්ෂේත්‍ර සමාලෝචනය කරන්න.",
