  "check.foundFew": "ඔබට පැහැදිලි කරගැනීමට අවශ්‍ය විය හැකි විස්තර කිහිපයක් අපට හමු විය.",
  "check.noQuestions": "මෙම සංශෝධනය සඳහා අවශ්‍ය අඩු ක්ෂේත්‍ර ප්‍රශ්න කිසිවක් ලැබුණේ නැත.",
  "check.changes": "පෙර දීමනාවෙන් වෙනස්කම්",
