  "check.reviewAgreement": "ගිවිසුම සමාලෝචනය කරන්න",
  "ask.title": "පිළිගැනීමට පෙර අසන්න",
  "ask.subtitle": "ප්‍රශ්න දීමනා සංශෝධනය {version} ට අමුණා ඇත.",
  "ask.none": "මෙම සංශෝධනය සඳහා අවශ්‍ය අඩු ක්ෂේත්‍ර ප්‍රශ්න නොමැත. අභිරුචි ප්‍රශ්න සෑදීම වත්මන් දත්ත API හි කොටසක් නොවේ.",
  "ask.saved": "මෙම ප්‍රශ්නය සහ දීමනා සංශෝධනය සඳහා පිළිතුර සුරකින ලදී.",
  "ask.answerLabel": "{question} සඳහා ඔබේ පිළිතුර",
  "ask.placeholder": "ඔබේ පැහැදිලි කිරීමේ සටහන ඇතුළත් කරන්න",
  "ask.save": "පිළිතුර සුරකින්න",
  "ask.immutable": "පිළිතුරු වෙනස් කළ නොහැකි අතර දීමනා කොන්දේසි වෙනස් නොකරයි. සෑම පිළිතුරක්ම පිවිසුණු ගිණුම යටතේ සටහන් වේ; සේවකයෙකු ඇතුළත් කළ සටහනක් සේවායෝජක තහවුරු කිරීමක් නොවේ.",
  "ask.copy": "ප්‍රශ්න පිටපත් කරන්න",
  "ask.copied": "ප්‍රශ්න පිටපත් කරන ලදී.",
  "ask.copyFailed": "පිටපත් කළ නොහැකි විය. අතින් පිටපත් කිරීමට ප්‍රශ්න පෙළ තෝරන්න.",
  "ask.continue": "ගිවිසුම වෙත ඉදිරියට",
  "ask.signedIn": "පිවිසුණු ගිණුම {id}",
  "export.title": "මගේ දත්ත බාගන්න",
  "export.intro": "ඔබේම වාර්තාවල පිටපතක් (පැතිකඩ, දීමනා, රැකියා ඉතිහාසය, වැඩ වාර්තා, පාස්පෝර්ට්, ටෝකන රහිත අක්තපත්‍ර, සුරක්ෂිත ගබඩා ලේඛන ලැයිස්තුව, සැලැස්ම සහ ක්‍රියාකාරකම්) මෙම උපාංගයේ ගොනුවක් ලෙස සුරකින්න. එය කොතැනකටවත් උඩුගත නොවේ. එය පෞද්ගලිකව තබාගන්න.",
  "export.button": "මගේ දත්ත ගොනුව සාදා බාගන්න",
  "export.working": "ඔබේ ගොනුව සූදානම් කරමින්…",
  "export.done": "ඔබේ ගොනුව සාදන ලදී. සෑම කොටසකම අයිතම ගණන ලැයිස්තුවේ දැක්වේ.",
  "export.unavailable": "කියවිය නොහැකි විය",
  "rv.title": "බඳවා ගැනීමේ නිලධාරියා සත්‍යාපනය",
  "rv.intro": "ඔබ හා සම්බන්ධ වූ පුද්ගලයා ඔහු නම් කරන සේවායෝජකයා විසින් තහවුරු කර ඇත්දැයි පරීක්ෂා කරන්න. ප්‍රකාශයට සහාය දක්වන දේ, නොගැලපෙන දේ සහ පරීක්ෂා කළ නොහැකි වූ දේ ORYQEN පෙන්වයි. නමක්, විද්‍යුත් තැපැල් ආකෘතියක් හෝ පැතිකඩ පිටුවක් සාක්ෂියක් ලෙස එය කිසිවිටෙක නොසලකන අතර, කිසිවෙකු අවංකදැයි තීරණය නොකරයි.",
  "rv.yourChecks": "ඔබේ බඳවා ගැනීමේ පරීක්ෂා",
  "rv.none": "තවම බඳවා ගැනීමේ පරීක්ෂා නැත.",
  "rv.employerConfirms": "සේවායෝජකයා තහවුරු කරයි",
  "rv.employerDisputes": "සේවායෝජකයා ප්‍රතික්ෂේප කරයි",
  "rv.noEmployerAnswer": "සේවායෝජකයාගේ පිළිතුරක් තවම නැත",
  "rv.open": "ප්‍රතිඵලය විවෘත කරන්න",
  "rv.newCheck": "බඳවා ගැනීමේ නිලධාරියෙකු පරීක්ෂා කරන්න",
  "rv.recruiterName": "ඔබට දුන් පරිදි බඳවා ගැනීමේ නිලධාරියාගේ නම",
  "rv.employer": "ඔහු නියෝජනය කරන බව පවසන සේවායෝජකයා",
  "rv.findOnOryqen": "මෙම සේවායෝජකයා ORYQEN හි සොයන්න",
  "rv.pickEmployer": "ORYQEN හි සේවායෝජක සංවිධාන",
  "rv.pickNote": "එය එම සංවිධානයමයි නම් පමණක් එකක් තෝරන්න. එවිට එහි අනුමත නියෝජිතයින්ට මෙම පුද්ගලයා තහවුරු කිරීමට හෝ ප්‍රතික්ෂේප කිරීමට හැක. ඔබ කවුදැයි ඔවුන්ට නොපෙනේ.",
  "rv.searchShort": "මුලින් සේවායෝජකයාගේ නමේ අකුරු හතරක් හෝ ටයිප් කරන්න.",
  "rv.searchNone": "එම නමින් ආරම්භ වන අනුමත නියෝජිතයෙකු සහිත ORYQEN සංවිධානයක් නැත. ඔබට තවමත් පරීක්ෂාව කළ හැක; නමුත් සේවායෝජකයාට මෙහි තහවුරු කළ නොහැක.",
  "rv.role": "ඔහු දුන් රැකියා තනතුර (විකල්ප)",
  "rv.email": "ඔහුගේ ව්‍යාපාරික විද්‍යුත් තැපැල් ලිපිනය (විකල්ප)",
  "rv.site": "ඔහු දුන් සේවායෝජකයාගේ වෙබ් අඩවිය (විකල්ප)",
  "rv.posting": "රැකියා දැන්වීමේ ලිපිනය (විකල්ප)",
  "rv.profile": "ඔහුගේ වෘත්තීය පැතිකඩ සබැඳිය (විකල්ප; ස්වයංක්‍රීයව කියවන්නේ නැත)",
  "rv.notice": "ඔබ තවත් පුද්ගලයෙකුගේ නම සහ සම්බන්ධතා තොරතුරු එක් අරමුණක් සඳහා ඇතුළත් කරයි: ඔබට ලැබුණු දීමනාවක් පරීක්ෂා කිරීම. ඒවා දින 90ක් පෞද්ගලිකව තබා ගන්නා අතර ඔබට සහ නම් කළ සේවායෝජකයාගේ අනුමත නියෝජිතයින්ට (ඔබේ අනන්‍යතාව නොමැතිව) පමණක් පෙන්වන අතර, ඔබට ඕනෑම වේලාවක මකා දැමිය හැක. ඔහුගේ පෞද්ගලික ජීවිතය, හැඳුනුම්පත් අංක හෝ පණිවිඩ ඇතුළත් නොකරන්න.",
  "rv.acknowledge": "මම තේරුම් ගතිමි; මෙම තොරතුරු ඇතුළත් කරන්නේ මගේම දීමනාව පරීක්ෂා කිරීමට පමණි.",
  "rv.check": "මෙම බඳවා ගැනීමේ නිලධාරියා පරීක්ෂා කරන්න",
