  "reminders.checkOpen": "දීමනා පරීක්ෂාව විවෘත කරන්න",
  "reminders.queue": "සංවිධාන නියෝජිතයෙකු ලෙස ඔබේ තීරණය බලා සිටින බඳවා ගැනීමේ ඉල්ලීම් {count} ක් ඇත.",
  "reminders.queueOpen": "සේවායෝජක වැඩබිම විවෘත කරන්න",
  "wa.title": "මෙම වාර්තාව සඳහා මගේ ලේඛන",
  "wa.intro": "ඔබේ සාක්ෂි සුරක්ෂිත ගබඩාවේ ලේඛන, උදාහරණයක් ලෙස වැටුප් පතක්, මෙම වාර්තාවට සම්බන්ධ කරන්න. සබැඳිය ඔබට පෞද්ගලිකයි: එය සේවායෝජකයාට, සමාලෝචකයෙකුට හෝ ඔබේ ගමන් බලපත්‍රය බෙදාගන්නා කිසිවෙකුට නොපෙනේ.",
  "wa.none": "තවම සම්බන්ධ කළ ලේඛන නැත.",
  "wa.pick": "සම්බන්ධ කිරීමට ලේඛනයක් තෝරන්න",
  "wa.attach": "ලේඛනය සම්බන්ධ කරන්න",
  "wa.detach": "සම්බන්ධය ඉවත් කරන්න",
  "wa.noVault": "ඔබේ සාක්ෂි සුරක්ෂිත ගබඩාව හිස්. මුලින් එහි ලේඛනයක් සුරකින්න.",
  "wa.error": "එය සාර්ථක නොවීය. නැවත උත්සාහ කරන්න.",
  "im.reading": "මෙම උපාංගයේ කියවමින්…",
  "im.review": "උපුටා ගත් පෙළ සමාලෝචනය කරන්න",
  "im.removePersonal": "ඔබට අවශ්‍ය නොවන පුද්ගලික තොරතුරු ඉවත් කරන්න. ඉදිරියට යාමෙන් පෙළ කෙටුම්පත පමණක් පිරේ; කොන්දේසි සුරැකීම සහ ඕනෑම විකල්ප AI කැමැත්තක් වෙන් ක්‍රියා වේ.",
  "im.shot.aria": "දේශීය තිරරූ කියවනය",
  "im.shot.title": "මෙම උපාංගයේ තිරරූපයක් කියවන්න",
  "im.shot.intro": "මුද්‍රිත ඉංග්‍රීසි පෙළ පමණි. ඔබේ රූපය මෙම උපාංගයේම පවතින අතර සුරකින්නේ හෝ උඩුගත කරන්නේ නැත. පෙළ හඳුනාගැනීම වැරදිය හැක; ඉදිරියට යාමට පෙර සමාලෝචනය කරන්න. මෙය OCR වේ, සජීවී AI විශ්ලේෂණයක් නොවේ.",
  "im.shot.file": "දීමනා තිරරූපය",
  "im.shot.cancel": "කියවීම අවලංගු කරන්න",
  "im.shot.use": "සමාලෝචනය කළ පෙළ භාවිත කරන්න",
  "im.shot.timeout": "කියවීම කල් ඉකුත් විය. කුඩා රූපයක් උත්සාහ කරන්න හෝ කොන්දේසි අතින් ඇතුළත් කරන්න.",
  "im.shot.badFile": "5 MB ට අඩු PNG හෝ JPEG තිරරූපයක් තෝරන්න. PDF සහ SVG සහාය නොදක්වයි.",
  "im.shot.tooBig": "මෙගාපික්සල් 12 ට වැඩි නොවන රූපයක් තෝරන්න.",
  "im.shot.unavailable": "දේශීය රූප කියවනය නොමැත. නැවත උත්සාහ කරන්න හෝ කොන්දේසි අතින් ඇතුළත් කරන්න.",
  "im.shot.noText": "පෙළ කියවිය නොහැකි විය. වඩා පැහැදිලි ඉංග්‍රීසි තිරරූපයක් උත්සාහ කරන්න හෝ කොන්දේසි අතින් ඇතුළත් කරන්න.",
  "im.shot.openFail": "රූපය විවෘත කළ නොහැකි විය.",
  "im.pdf.aria": "දේශීය PDF කියවනය",
  "im.pdf.title": "මෙම උපාංගයේ පෙළ PDF එකක් කියවන්න",
  "im.pdf.intro": "ඔබේ PDF මෙම උපාංගයේම පවතින අතර සුරකින්නේ හෝ උඩුගත කරන්නේ නැත. පෙළ පදනම් වූ PDF පමණක් ක්‍රියා කරයි (5 MB දක්වා සහ පිටු {pages}); ස්කෑන් කළ PDF සඳහා තිරරූ කියවනය අවශ්‍යයි. උපුටා ගත් පෙළ අසම්පූර්ණ හෝ අනුපිළිවෙල නැති විය හැක, එබැවින් ඉදිරියට යාමට පෙර සමාලෝචනය කරන්න. මෙය පෙළ උපුටා ගැනීමකි, AI විශ්ලේෂණයක් නොවේ.",
  "im.pdf.file": "දීමනා PDF",
  "im.pdf.readLine": "පිටු {total} න් {read} ක් කියවා ඇත.",
