  "im.pdf.use": "මෙම පෙළ භාවිත කරන්න",
  "im.pdf.failed": "මෙම PDF කියවිය නොහැකි විය. වෙනත් ගොනුවක් උත්සාහ කරන්න හෝ පෙළ අලවන්න.",
  "im.pdf.readOne": "පිටු {total} න් {read} ක් කියවා ඇත.",
  "ev.tooBig": "ලේඛනය බයිට් 16,000 ට වැඩි නොවිය යුතුය.",
  "ev.slots": "මෙම ලේඛනයට සාක්ෂි ස්ථාන {needed} ක් අවශ්‍යයි; {left} ක් ඉතිරිය. කෙටි ලේඛනයක් භාවිත කරන්න හෝ ප්‍රකාශයක් ඉවත් කරන්න.",
  "ev.readFail": "ලේඛනය කියවිය නොහැකි විය.",
  "ev.aria": "ලේඛන සාක්ෂි ආයාත කරන්න",
  "ev.title": "පෙළ ලේඛන සාක්ෂි ආයාත කරන්න",
  "ev.intro": "UTF-8 .txt ගොනුවක් දේශීයව කියවා එහි උපුටා ගැනීම් සමාලෝචනය කරන්න. පෞද්ගලික වැඩ කෙටුම්පත සුරකින තුරු කිසිවක් නොයවයි. මුල් ගොනුව උඩුගත කිරීම හෝ රඳවා ගැනීමක් නොවේ; ආයාත කළ පෙළ ස්වාධීනව සත්‍යාපනය කර නැත.",
  "ev.file": "පෙළ ලේඛනය",
  "ev.reading": "මෙම උපාංගයේ ලේඛනය කියවමින්…",
  "ev.ready": "සංස්කරණය කළ හැකි සාක්ෂි ප්‍රකාශ {count} ක් සූදානම්. එක් කිරීමට පෙර රහස් තොරතුරු පරීක්ෂා කරන්න.",
  "ev.preview": "ආයාත කළ පෙළ පෙරදසුන",
  "ev.cancel": "ලේඛන ආයාතය අවලංගු කරන්න",
  "ev.add": "උපුටා ගැනීම් කෙටුම්පතට එක් කරන්න",
  "au.welcomeAria": "ORYQEN වෙත සාදරයෙන් පිළිගනිමු",
  "au.eyebrow1": "ඔබේ රැකියාව, වටහාගත්",
  "au.eyebrow2": "සෑම පියවරකම පැහැදිලිකම",
  "au.headline": "වඩා හොඳ රැකියාවක් ආරම්භ වන්නේ වටහා ගැනීමෙනි.",
  "au.asideText": "රැකියා කොන්දේසි වටහා ගැනීමට, පැහැදිලි වාර්තාවක් තබා ගැනීමට සහ විශ්වාසයෙන් ඉදිරියට යාමට හවුල් ස්ථානයක්.",
  "au.asideFooter": "පැහැදිලි කොන්දේසි. හවුල් අවබෝධය.",
