  "au.reg.employerSub": "සංවිධානයක් නියෝජනය කර රැකියා කොන්දේසි පැහැදිලි කරන්න.",
  "au.reg.employerNote": "සේවායෝජක අධිකාරියට වෙනම සමාලෝචිත සමාගම් සාමාජිකත්වයක් අවශ්‍යයි. ගිණුමක් තේරීමෙන් අනුමැතියක් නොලැබේ.",
