  "au.reg.yourName": "ඔබේ නම",
  "au.reg.confirmPassword": "මුරපදය තහවුරු කරන්න",
  "au.reg.passwordHelp": "අකුරු 12–128ක් භාවිත කරන්න. දිගු, අනන්‍ය මුරවැකියක් හොඳින් ක්‍රියා කරයි.",
  "au.reg.confirmSession": "ඔබේ විද්‍යුත් තැපැල් සබැඳිය Supabase වෙතින් ආපසු පැමිණ ඇත. ඔබේ සැසිය වලංගු කිරීමට සහ පෞද්ගලික පැතිකඩ සැකසීමට ඉදිරියට යන්න.",
  "au.reg.confirmEmailTo": "ඔබේ පෞද්ගලික පැතිකඩ වෙත යාමට ඔබේ විද්‍යුත් තැපෑල තහවුරු කරන්න.",
