  "au.rec.lostNote": "සත්‍යාපක ප්‍රවේශය අහිමි වීමට ස්වාධීනව සමාලෝචනය කළ ප්‍රතිසාධන ක්‍රියාවලියක් අවශ්‍යයි; මෙම යෙදුමට එය මඟ හැරිය නොහැක.",
