  "ai.checking": "AI ලබා ගත හැකිදැයි පරීක්ෂා කරමින්…",
  "ai.unavailable": "ක්‍රියාකරු සැපයුම්කරුවෙකු වින්‍යාස කර එහි දත්ත සැකසුම් ප්‍රතිපත්තිය අනුමත කරන තෙක් සජීවී AI ලබා ගත නොහැක. දීමනා පෙළ කිසිවක් යවා නැත. දේශීය සමාලෝචනයක් සඳහා ඉහත දේශීය රීතිවලින් කොන්දේසි යෝජනා කරන්න භාවිත කරන්න; එය AI නොවේ.",
