  "ai.pauseNote": "අත්හිටුවා ඇති අතරතුර සැපයුම්කරුවෙකුට කිසිවක් නොයවයි. දේශීය රීති සහ අතින් සමාලෝචනය ලබා ගත හැක.",
  "ai.sendIntro": "සමාලෝචනය කළ පහත පෙළ උපදේශාත්මක විශ්ලේෂණයක් සඳහා {provider} ({model}) වෙත යවන්න. පළමුව නම්, සම්බන්ධතා විස්තර, හැඳුනුම්පත් සහ රහස් කොන්දේසි ඉවත් කරන්න.",
  "ai.redactNote": "ස්වයංක්‍රීය සංස්කරණය සමහර හඳුනාගත හැකි හැඳුනුම් ඉවත් කරයි. එයට නිර්නාමිකභාවය සහතික කළ නොහැක. කැමැත්ත දීමට පෙර සම්පූර්ණ පෙරදසුන පරීක්ෂා කරන්න.",
  "ai.textLabel": "යවන පෙළ",
  "ai.region": "ක්‍රියාකරු හෙළි කළ සැකසුම් කලාපය: {region}. දත්ත භාවිතය සහ රඳවා ගැනීම: {use}",
  "ai.noRecall": "යැවූ පසු, දත්ත සැපයුම්කරුගෙන් ආපසු ගත නොහැක. සෑම ඉල්ලීමකටම නව කැමැත්තක් අවශ්‍යයි; පෙළ හෝ සැපයුම්කරු ප්‍රතිපත්තිය වෙනස් කිරීමට නැවත කැමැත්ත අවශ්‍යයි.",
  "ai.mayBeWrong": "ප්‍රතිචාරය වැරදි විය හැක. එයට සමාගමක් සත්‍යාපනය කිරීමට, නීතිමය අනුකූලතාව තීරණය කිරීමට හෝ ගිවිසුමක් තහවුරු කිරීමට නොහැක. දීමනා පෙළ නොමැතිව අවම අවසර රිසිට්පතක් රඳවා ගනී. නැවත උත්සාහ කිරීම තවත් සීමිත ඉල්ලීමක් පරිභෝජනය කරයි.",
