  "ai.retryOne": "AI නැවත මිනිත්තු 1ක් පමණ ඇතුළත උත්සාහ කරන්න. ඔබේ පෙළ සුරකින ලද හෝ පෝලිමක තබන ලද්දක් නොවේ; දේශීය රීති සහ අතින් සමාලෝචනය දැන් ක්‍රියා කරයි.",
