  "ai.noChange": "මෙම යෝජනා ඔබේ සුරකින ලද දීමනාව වෙනස් නොකරයි. සුරැකීමට පෙර සමාලෝචනය කළ කොන්දේසි දීමනා ක්ෂේත්‍රවල ඇතුළත් කරන්න.",
