  "add.employerNote": "தொழிலாளியிடம் அவரது கணக்கு அடையாளத்தைக் கேளுங்கள். தேர்ந்தெடுத்த அமைப்புக்கு உங்களிடம் தற்போதைய சுயாதீன அதிகாரம் இருக்க வேண்டும்; இரு தரப்பாகவும் உறுதிப்படுத்த முடியாது.",
  "add.idsNote": "இந்த அடையாளங்கள் பங்கேற்பாளர்களை அடையாளம் காட்டுகின்றன; அவை அணுகலை வழங்காது. சேவையகம் உங்கள் உள்நுழைந்த கணக்கையும் தற்போதைய அதிகாரத்தையும் சரிபார்க்கிறது.",
  "add.analyzeNote": "‘சலுகையை ஆய்வு செய்’ மதிப்பாய்வு செய்த புலங்களைச் சேமித்து விடுபட்ட நிபந்தனைகளைச் சரிபார்க்கும். ஒட்டிய உரை தானாக நிபந்தனைகளாகச் சேமிக்கப்படாது; உள்ளூர்ப் பரிந்துரைகளைப் பயன்படுத்தி முதலில் புலங்களை மதிப்பாய்வு செய்யுங்கள்.",
  "add.checking": "சலுகையைச் சரிபார்க்கிறது…",
