  "ask.subtitle": "கேள்விகள் சலுகைத் திருத்தம் {version} உடன் இணைக்கப்பட்டுள்ளன.",
  "ask.none": "இந்தத் திருத்தத்திற்கு விடுபட்ட புலக் கேள்விகள் எதுவும் தேவையில்லை. தனிப்பயன் கேள்விகளை உருவாக்குவது தற்போதைய தரவுத்தள API இன் பகுதி அல்ல.",
  "ask.saved": "இந்தக் கேள்விக்கும் சலுகைத் திருத்தத்திற்கும் பதில் சேமிக்கப்பட்டது.",
