  "export.title": "என் தரவைப் பதிவிறக்கு",
  "export.intro": "உங்கள் சொந்தப் பதிவுகளின் (சுயவிவரம், சலுகைகள், வேலை வரலாறு, வேலைப் பதிவுகள், கடவுச்சீட்டு, டோக்கன் இல்லாத சான்றுகள், பெட்டக ஆவணப் பட்டியல், திட்டம், செயல்பாடு) நகலை இந்தச் சாதனத்தில் கோப்பாகச் சேமிக்கவும். அது எங்கும் பதிவேற்றப்படாது. அதைத் தனிப்பட்டதாக வைத்திருங்கள்.",
  "export.button": "என் தரவுக் கோப்பை உருவாக்கிப் பதிவிறக்கு",
  "export.working": "உங்கள் கோப்பைத் தயாரிக்கிறது…",
  "export.done": "உங்கள் கோப்பு உருவாக்கப்பட்டது. ஒவ்வொரு பிரிவிலும் உள்ள உருப்படிகளின் எண்ணிக்கையைப் பட்டியல் காட்டுகிறது.",
  "export.unavailable": "படிக்க முடியவில்லை",
  "rv.title": "ஆட்சேர்ப்பாளர் சரிபார்ப்பு",
  "rv.intro": "உங்களைத் தொடர்புகொண்டவர் தான் குறிப்பிடும் முதலாளியால் உறுதிப்படுத்தப்பட்டுள்ளாரா எனச் சரிபார்க்கவும். கூற்றை ஆதரிப்பவை, பொருந்தாதவை, சரிபார்க்க முடியாதவை ஆகியவற்றை ORYQEN காட்டுகிறது. பெயர், மின்னஞ்சல் வடிவம் அல்லது சுயவிவரப் பக்கத்தை அது ஒருபோதும் சான்றாகக் கருதாது; யாரேனும் நேர்மையானவரா என்பதையும் அது தீர்மானிக்காது.",
  "rv.yourChecks": "உங்கள் ஆட்சேர்ப்பு சரிபார்ப்புகள்",
  "rv.none": "இதுவரை ஆட்சேர்ப்புச் சரிபார்ப்புகள் இல்லை.",
  "rv.employerConfirms": "முதலாளி உறுதிப்படுத்துகிறார்",
  "rv.employerDisputes": "முதலாளி மறுக்கிறார்",
  "rv.noEmployerAnswer": "முதலாளியின் பதில் இன்னும் இல்லை",
  "rv.open": "முடிவைத் திற",
  "rv.newCheck": "ஆட்சேர்ப்பாளரைச் சரிபார்",
  "rv.recruiterName": "உங்களுக்குத் தரப்பட்டபடி ஆட்சேர்ப்பாளரின் பெயர்",
  "rv.employer": "அவர் பிரதிநிதித்துவப்படுத்துவதாகக் கூறும் முதலாளி",
  "rv.findOnOryqen": "இந்த முதலாளியை ORYQEN இல் தேடு",
  "rv.pickEmployer": "ORYQEN இல் உள்ள முதலாளி அமைப்புகள்",
  "rv.pickNote": "அதே அமைப்பாக இருந்தால் மட்டுமே ஒன்றைத் தேர்ந்தெடுக்கவும். அதன் அங்கீகரிக்கப்பட்ட பிரதிநிதிகள் இந்த நபரை உறுதிப்படுத்தலாம் அல்லது மறுக்கலாம். நீங்கள் யார் என்பது அவர்களுக்குத் தெரியாது.",
  "rv.searchShort": "முதலில் முதலாளியின் பெயரின் குறைந்தது நான்கு எழுத்துகளைத் தட்டச்சு செய்யவும்.",
  "rv.searchNone": "அந்தப் பெயரில் தொடங்கி அங்கீகரிக்கப்பட்ட பிரதிநிதி உள்ள ORYQEN அமைப்பு எதுவும் இல்லை. நீங்கள் இன்னும் சரிபார்ப்பை நடத்தலாம்; ஆனால் முதலாளியால் இங்கே உறுதிப்படுத்த முடியாது.",
  "rv.role": "அவர் கூறிய பதவி (விருப்பம்)",
  "rv.email": "அவரது வணிக மின்னஞ்சல் முகவரி (விருப்பம்)",
  "rv.site": "அவர் கூறிய முதலாளியின் இணையதளம் (விருப்பம்)",
  "rv.posting": "வேலை விளம்பர முகவரி (விருப்பம்)",
  "rv.profile": "அவரது தொழில்முறை சுயவிவர இணைப்பு (விருப்பம்; தானாகப் படிக்கப்படாது)",
  "rv.notice": "நீங்கள் வேறொருவரின் பெயரையும் தொடர்பு விவரங்களையும் ஒரே நோக்கத்திற்காக உள்ளிடுகிறீர்கள்: உங்களுக்கு வந்த சலுகையைச் சரிபார்ப்பது. அவை 90 நாட்கள் தனிப்பட்ட முறையில் வைக்கப்படும்; உங்களுக்கும் குறிப்பிட்ட முதலாளியின் அங்கீகரிக்கப்பட்ட பிரதிநிதிகளுக்கும் (உங்கள் அடையாளம் இல்லாமல்) மட்டுமே காட்டப்படும்; எப்போது வேண்டுமானாலும் நீக்கலாம். அவரது தனிப்பட்ட வாழ்க்கை, அடையாள எண்கள் அல்லது செய்திகளை உள்ளிட வேண்டாம்.",
  "rv.acknowledge": "நான் புரிந்துகொண்டேன்; இந்த விவரங்களை என் சொந்தச் சலுகையைச் சரிபார்க்க மட்டுமே உள்ளிடுகிறேன்.",
  "rv.check": "இந்த ஆட்சேர்ப்பாளரைச் சரிபார்",
  "rv.working": "சரிபார்க்கிறது…",
  "rv.retryNote": "மீண்டும் முயலவும்; அதே கோரிக்கை மீண்டும் பயன்படுத்தப்படுவதால் நகல் உருவாகாது.",
  "rv.loadError": "ஆட்சேர்ப்புச் சரிபார்ப்பை ஏற்ற முடியவில்லை. இணைந்த பின் மீண்டும் முயலவும்.",
  "rv.result": "ஆட்சேர்ப்பாளர் சரிபார்ப்பு முடிவு",
  "rv.back": "என் சரிபார்ப்புகளுக்குத் திரும்பு",
