  "ag.ackedNotConfirmed": "ஒப்புக்கொண்டார்; உறுதிப்படுத்தவில்லை",
  "ag.awaitingAck": "ஒப்புதலுக்காகக் காத்திருக்கிறது",
  "ag.unresolvedAria": "தீர்க்கப்படாத ஒப்புதல்கள்",
  "ag.unresolvedTitle": "தீர்க்கப்படாத உருப்படிகள்",
  "ag.unresolvedNote": "ஒரு உருப்படியை ஒப்புக்கொள்வது அதைத் தீர்க்காது, பாதுகாப்பானது என அறிவிக்காது. ஒவ்வொரு பங்கேற்பாளரும் ஒவ்வொரு உருப்படியையும் சுயாதீனமாக மதிப்பாய்வு செய்ய வேண்டும்.",
