  "ag.noUnresolved": "இந்தப் பதிப்பில் தீர்க்கப்படாத உருப்படிகள் இல்லை. உங்கள் ஒப்புதலைப் பதிவு செய்யும் முன் முழு விதிமுறைகளையும் மதிப்பாய்வு செய்யவும்.",
