  "wa.error": "அது செயல்படவில்லை. மீண்டும் முயலவும்.",
  "im.reading": "இந்தச் சாதனத்தில் படிக்கிறது…",
  "im.review": "பிரித்தெடுத்த உரையை மதிப்பாய்வு செய்",
  "im.removePersonal": "தேவையில்லாத தனிப்பட்ட விவரங்களை நீக்கவும். தொடர்வது உரை வரைவை மட்டுமே நிரப்பும்; விதிமுறைகளைச் சேமிப்பதும் விருப்ப AI ஒப்புதலும் தனிச் செயல்கள்.",
  "im.shot.aria": "உள்ளூர் திரைப்பட வாசிப்பான்",
  "im.shot.title": "இந்தச் சாதனத்தில் திரைப்படத்தைப் படி",
  "im.shot.intro": "அச்சிட்ட ஆங்கில உரை மட்டும். உங்கள் படம் இந்தச் சாதனத்திலேயே இருக்கும்; சேமிக்கவோ பதிவேற்றவோ படாது. உரை அடையாளம் தவறக்கூடும்; தொடரும் முன் மதிப்பாய்வு செய்யவும். இது OCR, நேரடி AI பகுப்பாய்வு அல்ல.",
  "im.shot.file": "சலுகைத் திரைப்படம்",
  "im.shot.cancel": "படிப்பதை ரத்துசெய்",
  "im.shot.use": "மதிப்பாய்வு செய்த உரையைப் பயன்படுத்து",
  "im.shot.timeout": "படிப்பது நேரம் முடிந்தது. சிறிய படத்தை முயலவும் அல்லது விதிமுறைகளைக் கையால் உள்ளிடவும்.",
  "im.shot.badFile": "5 MB க்குக் குறைவான PNG அல்லது JPEG திரைப்படத்தைத் தேர்ந்தெடுக்கவும். PDF, SVG ஆதரிக்கப்படாது.",
  "im.shot.tooBig": "12 மெகாபிக்சலுக்கு மிகாத படத்தைத் தேர்ந்தெடுக்கவும்.",
  "im.shot.unavailable": "உள்ளூர் பட வாசிப்பான் கிடைக்கவில்லை. மீண்டும் முயலவும் அல்லது விதிமுறைகளைக் கையால் உள்ளிடவும்.",
  "im.shot.noText": "உரையைப் படிக்க முடியவில்லை. தெளிவான ஆங்கிலத் திரைப்படத்தை முயலவும் அல்லது விதிமுறைகளைக் கையால் உள்ளிடவும்.",
  "im.shot.openFail": "படத்தைத் திறக்க முடியவில்லை.",
  "im.pdf.aria": "உள்ளூர் PDF வாசிப்பான்",
  "im.pdf.title": "இந்தச் சாதனத்தில் உரை PDF ஐப் படி",
  "im.pdf.intro": "உங்கள் PDF இந்தச் சாதனத்திலேயே இருக்கும்; சேமிக்கவோ பதிவேற்றவோ படாது. உரை அடிப்படையிலான PDF மட்டுமே செயல்படும் (5 MB வரை, {pages} பக்கங்கள்); ஸ்கேன் செய்த PDF க்கு திரைப்பட வாசிப்பான் தேவை. பிரித்தெடுத்த உரை முழுமையற்றதாகவோ வரிசை தவறியதாகவோ இருக்கலாம்; தொடரும் முன் மதிப்பாய்வு செய்யவும். இது உரைப் பிரித்தெடுப்பு, AI பகுப்பாய்வு அல்ல.",
  "im.pdf.file": "சலுகை PDF",
  "im.pdf.readLine": "{total} பக்கங்களில் {read} படிக்கப்பட்டன.",
  "im.pdf.truncated": "முதல் {chars} எழுத்துகளும் {pages} பக்கங்களும் மட்டுமே வைக்கப்படும்.",
  "im.pdf.use": "இந்த உரையைப் பயன்படுத்து",
  "im.pdf.failed": "இந்த PDF ஐப் படிக்க முடியவில்லை. வேறு கோப்பை முயலவும் அல்லது உரையை ஒட்டவும்.",
  "im.pdf.readOne": "{total} பக்கத்தில் {read} படிக்கப்பட்டது.",
  "ev.tooBig": "ஆவணம் அதிகபட்சம் 16,000 பைட்டுகள் இருக்க வேண்டும்.",
  "ev.slots": "இந்த ஆவணத்துக்கு {needed} சான்று இடங்கள் தேவை; {left} மட்டுமே மீதம். சிறிய ஆவணத்தைப் பயன்படுத்தவும் அல்லது ஒரு கூற்றை நீக்கவும்.",
  "ev.readFail": "ஆவணத்தைப் படிக்க முடியவில்லை.",
  "ev.aria": "ஆவணச் சான்றுகளை இறக்குமதி செய்",
  "ev.title": "உரை ஆவணச் சான்றுகளை இறக்குமதி செய்",
  "ev.intro": "UTF-8 .txt கோப்பை உள்ளூரில் படித்து, அதன் பகுதிகளை மதிப்பாய்வு செய்யவும். தனிப்பட்ட பணி வரைவைச் சேமிக்கும் வரை எதுவும் அனுப்பப்படாது. மூலக் கோப்பு பதிவேற்றப்படவோ வைக்கப்படவோ மாட்டாது; இறக்குமதி செய்த உரை சுயாதீனமாகச் சரிபார்க்கப்படவில்லை.",
  "ev.file": "உரை ஆவணம்",
  "ev.reading": "இந்தச் சாதனத்தில் ஆவணத்தைப் படிக்கிறது…",
  "ev.ready": "திருத்தக்கூடிய {count} சான்றுக் கூற்றுகள் தயார். சேர்ப்பதற்கு முன் ரகசியத் தகவல் உள்ளதா எனப் பார்க்கவும்.",
  "ev.preview": "இறக்குமதி செய்த உரை முன்னோட்டம்",
  "ev.cancel": "ஆவண இறக்குமதியை ரத்துசெய்",
  "ev.add": "பகுதிகளை வரைவில் சேர்",
  "au.welcomeAria": "ORYQEN க்கு வரவேற்கிறோம்",
