  "au.reg.employerNote": "முதலாளி அதிகாரத்துக்குத் தனியாக மதிப்பாய்வு செய்யப்பட்ட நிறுவன உறுப்பினர் தகுதி தேவை. கணக்கைத் தேர்ந்தெடுப்பது ஒப்புதல் வழங்காது.",
  "au.reg.checkInbox": "உங்கள் இன்பாக்ஸைப் பார்க்கவும்",
  "au.reg.sentStatus": "இந்த முகவரிக்குப் பதிவு கிடைக்குமானால், உறுதிப்படுத்தும் இணைப்புக்காக உங்கள் மின்னஞ்சலைப் பார்க்கவும். ஏற்கனவே உள்ள கணக்குகள் உள்நுழையலாம்.",
  "au.reg.sentNext": "இணைப்பைத் திறந்து, மின்னஞ்சலை உறுதிப்படுத்தி, சுயவிவரத்தை முடிக்கவும். வரவில்லை எனில் ஸ்பேமைப் பார்க்கவும்.",
