  "au.reg.confirmSession": "உங்கள் மின்னஞ்சல் இணைப்பு Supabase இலிருந்து திரும்பியுள்ளது. உங்கள் அமர்வைச் சரிபார்த்து தனிப்பட்ட சுயவிவரத்தை அமைக்கத் தொடரவும்.",
