  "au.reg.anotherEmail": "மற்றொரு சரிபார்ப்பு மின்னஞ்சல் வேண்டுமா?",
  "au.reg.requesting": "மின்னஞ்சலைக் கோருகிறது…",
  "au.reg.resendIn": "மீண்டும் அனுப்புதல் {seconds} வினாடியில் கிடைக்கும்",
  "au.reg.resend": "சரிபார்ப்பு மின்னஞ்சலை மீண்டும் அனுப்பு",
  "au.reg.resendNote": "கோரிக்கைகளுக்கு இடையே குறைந்தது ஒரு நிமிடம் காத்திருக்கவும். மின்னஞ்சல் வர சில நிமிடங்கள் ஆகலாம்.",
  "au.reg.resendWait": "மற்றொரு மின்னஞ்சலைக் கோரும் முன் ஒரு நிமிடம் காத்திருக்கவும்.",
  "au.reg.resendDone": "இந்த முகவரிக்கு உறுதிப்படுத்தப்படாத கணக்கு இருந்தால், புதிய சரிபார்ப்பு மின்னஞ்சல் கோரப்பட்டுள்ளது. இன்பாக்ஸ் மற்றும் ஸ்பேம் கோப்புறையைப் பார்க்கவும்.",
  "au.reg.resendFailed": "மற்றொரு மின்னஞ்சலைக் கோர முடியவில்லை.",
  "au.reg.mismatch": "கடவுச்சொற்கள் பொருந்தவில்லை. இரு புலங்களையும் சரிபார்க்கவும்.",
  "au.reg.needName": "தொடர உங்கள் பெயரை உள்ளிடவும்.",
  "au.reg.openLink": "உங்கள் மின்னஞ்சலில் உள்ள சரிபார்ப்பு இணைப்பைத் திறக்கவும் அல்லது கீழே புதிய இணைப்பைக் கோரவும்.",
  "au.reg.noSession": "உங்கள் அமர்வை நிறுவ முடியவில்லை. உள்நுழையவும் அல்லது புதிய மின்னஞ்சலைக் கோரவும்.",
  "au.reg.needDisplay": "தொடர காட்சிப் பெயரை உள்ளிடவும்.",
  "au.reg.linkInvalid": "இந்தச் சரிபார்ப்பு இணைப்பு செல்லாதது அல்லது காலாவதியானது. கீழே மற்றொரு மின்னஞ்சலைக் கோரவும்; முகவரியை ஏற்கனவே உறுதிப்படுத்தியிருந்தால் உள்நுழையவும்.",
  "au.reg.cannotContinue": "தொடர முடியவில்லை.",
  "au.backToSignIn": "உள்நுழைவுக்குத் திரும்பு",
  "au.rec.sentTitle": "உங்கள் இன்பாக்ஸைப் பார்க்கவும்",
  "au.rec.sentStatus": "இந்த முகவரிக்குக் கணக்கு இருந்தால், மீட்பு இணைப்புக்காக அதன் இன்பாக்ஸைப் பார்க்கவும். கணக்குத் தகவல் இங்கே வெளியிடப்படாது.",
  "au.rec.sentNote": "ஸ்பேமைப் பார்த்து, வர சில நிமிடங்கள் அனுமதிக்கவும்.",
  "au.rec.anotherEmail": "வேறு மின்னஞ்சலை முயல்",
  "au.rec.doneTitle": "கடவுச்சொல் புதுப்பிக்கப்பட்டது",
  "au.rec.doneStatus": "உங்கள் கடவுச்சொல் மாற்றப்பட்டது. புதிய கடவுச்சொல்லுடன் மீண்டும் உள்நுழையவும்.",
  "au.rec.confirmNote": "இந்தக் கடவுச்சொல் மீட்டமைப்பை நீங்கள் கோரியிருந்தால் மட்டுமே தொடரவும். இந்தப் பக்கத்தைத் திறப்பதால் மட்டும் மீட்பு இணைப்பு பயன்படுத்தப்படாது.",
  "au.rec.assuranceNote": "உங்கள் மீட்பு இணைப்பு உறுதிப்படுத்தப்பட்டது. தொடர உங்கள் கணக்கின் அங்கீகாரி தேவைகளைச் சரிபார்க்கவும்.",
  "au.rec.mfaNote": "உங்கள் தற்போதைய அங்கீகாரி இன்னும் தேவை. மின்னஞ்சல் மீட்பு MFA ஐ நீக்காது.",
  "au.rec.code": "அங்கீகாரி குறியீடு",
  "au.rec.lostNote": "அங்கீகாரி அணுகல் இழப்புக்கு சுயாதீனமாக மதிப்பாய்வு செய்யப்படும் மீட்புச் செயல்முறை தேவை; இந்தப் பயன்பாடு அதைத் தவிர்க்க முடியாது.",
  "au.rec.newPassword": "புதிய கடவுச்சொல்",
  "au.rec.confirmNew": "புதிய கடவுச்சொல்லை உறுதிப்படுத்து",
  "au.rec.signsOut": "கடவுச்சொல்லை மாற்றினால் அனைத்துச் சாதனங்களிலும் புதுப்பிப்பு அமர்வுகள் வெளியேற்றப்படும். தற்போதைய அணுகல் டோக்கன்கள் அமைக்கப்பட்ட வழங்குநர் அட்டவணைப்படி காலாவதியாகும்.",
  "au.rec.mismatch": "கடவுச்சொற்கள் பொருந்தவில்லை.",
  "au.rec.failed": "மீட்பை முடிக்க முடியவில்லை.",
  "au.rec.send": "மீட்பு மின்னஞ்சலை அனுப்பு",
  "au.rec.confirmLink": "மீட்பு இணைப்பை உறுதிப்படுத்து",
  "au.rec.retryAuth": "அங்கீகாரிச் சரிபார்ப்பை மீண்டும் முயல்",
