  "as.cat.finance": "நிதிக் கடமைகள்",
  "as.i.salary.l": "ஊதியத் தொகை",
  "as.i.salary.q": "கட்டணங்கள், படிகளைத் தவிர்த்து ஒரு அடிப்படை ஊதியத் தொகையை உறுதிப்படுத்தவும்.",
