  "as.i.currency.q": "மூன்றெழுத்து ஊதிய நாணயக் குறியீட்டைக் குறிப்பிடவும்.",
  "as.i.payPeriod.l": "ஊதியக் காலம்",
  "as.i.payPeriod.q": "ஊதியம் மணிக்கு, நாளுக்கு, வாரத்துக்கு, மாதத்துக்கு, ஆண்டுக்கு அல்லது திட்டத்துக்கு என்பதை உறுதிப்படுத்தவும்.",
