  "ai.noChange": "இந்தப் பரிந்துரைகள் உங்கள் சேமித்த சலுகையை மாற்றாது. சேமிக்கும் முன் மதிப்பாய்வு செய்த விதிமுறைகளைச் சலுகைப் புலங்களில் உள்ளிடவும்.",
