  "ai.out.quota": "ஒதுக்கீடு எட்டப்பட்டது",
  "ai.out.paused": "இடைநிறுத்தப்பட்டது, எதுவும் அனுப்பப்படவில்லை",
  "ai.out.budget": "பயன்பாட்டு வரவுசெலவு எட்டப்பட்டது",
