  "pp.loadError": "கடவுச்சீட்டை ஏற்ற முடியவில்லை.",
  "pp.createError": "கடவுச்சீட்டு உருவாக்கத்தை உறுதிப்படுத்த முடியவில்லை. மீண்டும் ஏற்றி முயலவும்.",
  "pp.downloadError": "தனிப்பட்ட பதிவிறக்கம் தோல்வியடைந்தது.",
  "pp.title": "பணிக் கடவுச்சீட்டு",
  "pp.tagline": "சுயாதீனமாகச் சரிபார்க்கப்பட்ட உங்கள் வேலை",
  "pp.private": "தனிப்பட்டது",
  "pp.loadingShort": "ஏற்றுகிறது…",
  "pp.unavailable": "கிடைக்கவில்லை",
  "pp.loadedCount": "{count} சரிபார்க்கப்பட்ட பதிவுகள் ஏற்றப்பட்டன",
  "pp.onlyYou": "இந்தக் கடவுச்சீட்டை நீங்கள் மட்டுமே பார்க்க முடியும்.",
  "pp.loading": "தனிப்பட்ட கடவுச்சீட்டை ஏற்றுகிறது…",
  "pp.signIn": "உங்கள் கடவுச்சீட்டை மீண்டும் திறக்க உள்நுழையவும்",
  "pp.createTitle": "உங்கள் தனிப்பட்ட கடவுச்சீட்டை உருவாக்குங்கள்",
  "pp.createSub": "சுயாதீனச் சரிபார்ப்புக்குப் பிறகு தகுதியான வேலையைக் காட்டுங்கள்.",
  "pp.create": "தனிப்பட்ட கடவுச்சீட்டை உருவாக்கு",
  "pp.history": "சரிபார்க்கப்பட்ட வேலை வரலாறு",
  "pp.noneTitle": "தகுதியான சரிபார்க்கப்பட்ட வேலை இன்னும் இல்லை",
  "pp.noneSub": "நிலுவையில் உள்ள, மறுக்கப்பட்ட, நிராகரிக்கப்பட்ட, திருத்தப்பட்ட, திரும்பப் பெறப்பட்ட பதிவுகள் விலக்கப்படும்.",
  "pp.viewRecords": "பணிப் பதிவுகளைப் பார்",
  "pp.employerRef": "முதலாளி குறிப்பு",
  "pp.period": "{start} – {end} · {hours} மணி",
  "pp.verified": "சரிபார்க்கப்பட்டது {date} · திருத்தம் {version}",
