  "re.title": "Recruiter-Bestätigungen",
  "re.intro": "Personen haben gefragt, ob die unten genannten Recruiter Ihre Organisation wirklich vertreten. Bestätigen Sie nur Personen, von denen Sie wissen, dass sie befugt sind; bestreiten Sie alle anderen. Ihre Entscheidung wird mit Ihrem Namen und der Zeit gespeichert, kann zurückgezogen werden, und eine Bestätigung läuft ab. Sie sehen nicht, wer gefragt hat.",
