  "as.st.stated": "angegeben",
  "as.st.missing": "fehlt",
  "as.st.uncertain": "unklar",
  "as.st.concern": "Bedenken",
  "as.ex.stated": "Das geprüfte Feld ist angegeben; es traf kein hinterlegtes ausdrückliches Bedenken zu. Das bestätigt weder die Angabe noch deren Fairness.",
  "as.ex.missing": "Für dieses Kriterium liegt kein geprüfter Nachweis vor. Fehlende Angaben sind kein Beleg für Fehlverhalten.",
  "as.ex.uncertain": "Dieser Wert ist ungeklärt oder liegt außerhalb des unterstützten Formats; bis zur Klärung gibt es keine Punkte.",
  "as.ex.concern": "Das geprüfte Feld nennt ausdrücklich eine Verpflichtung, die Aufmerksamkeit erfordert. Das ist ein beratender Hinweis, keine Feststellung von Rechtswidrigkeit.",
  "as.meaning": "Punkte aus 20 gleich gewichteten Klarheits- und Schutzprüfungen (je 5). Höher heißt: mehr geprüfte Bedingungen sind ohne hinterlegtes ausdrückliches Bedenken angegeben – nicht: ein sichererer Arbeitgeber oder ein fairer Marktlohn.",
  "as.limitations": "Produkt-Checkliste, keine empirisch validierte Bewertung, keine Rechtsauskunft, kein Gehaltsvergleich und keine Sicherheitsgarantie. Angaben können falsch sein. Regeln können Risiken und Widersprüche übersehen. Die Seriosität des Arbeitgebers, unabhängige Bestätigung und KI-Beobachtungen sind ausgeschlossen. Es werden keine landesspezifischen rechtlichen Schwellenwerte angewendet.",
  "as.aria": "Indikatoren zur Fairness des Angebots",
  "as.loading": "Bewertung der gespeicherten Bedingungen wird geladen…",
  "as.retry": "Bewertung erneut versuchen",
  "as.changed": "Dieses Angebot hat sich geändert. Öffnen Sie das gespeicherte Angebot erneut, bevor Sie die Bewertung ansehen.",
  "as.unavailable": "Bewertung nicht verfügbar.",
  "as.basisRevision": "Revision {n}",
