  "as.counts": "{stated} angegeben · {missing} fehlen · {uncertain} unklar · {concern} ausdrückliche Bedenken",
  "as.employerNote": "Arbeitgeberprüfung: von dieser Punktzahl nicht bewertet. Organisationsnachweise und Befugnis müssen gesondert geprüft werden. KI-Vorschläge ändern diese Punktzahl nie automatisch.",
  "as.detailsSummary": "Nachweise, Abzüge und nächste Schritte",
  "as.itemTitle": "{label}: {points}/5 · {status}",
  "as.engine": "Bewertungsmodul: {version}",
  "as.draftAria": "Indikatoren des Angebotsentwurfs",
  "as.draftTitle": "Diesen Entwurf lokal prüfen",
  "as.draftIntro": "Prüfen Sie die Felder oben und kontrollieren Sie vor dem Speichern die Klarheits- und Schutzindikatoren. Das nutzt lokale Regeln, keine KI. Für diese ungespeicherte Vorschau ist keine verknüpfte Organisation nötig; das Speichern erfordert weiterhin eine Serverberechtigung.",
  "as.draftButton": "Entwurfsindikatoren prüfen",
  "as.draftChanged": "Felder geändert. Prüfen Sie den Entwurf erneut für ein aktuelles Ergebnis.",
  "ra.aria": "Regelbasierte Hinweise",
  "ra.intro": "Lokaler Phrasenabgleich, keine KI und keine Rechtsbewertung. Ihre Bedingungen sind Behauptungen, keine bestätigten Tatsachen. Prüfen Sie den gesamten Zusammenhang, einschließlich Verneinungen und Ausnahmen.",
  "ra.none": "Keine hinterlegten Warnphrasen getroffen. Das ist keine Zusicherung, dass das Angebot fair, sicher oder vollständig ist.",
  "ra.more": "Weitere Fragen zur Überlegung",
  "ra.notice": "Hinweis: Regelbasierte Heuristiken können weder Firmenregistrierung noch Arbeitgeberbefugnis oder Rechtsgültigkeit bestätigen.",
  "ra.w.unpaid-trial.t": "Formulierung zur Probezeit-Vergütung prüfen",
  "ra.w.unpaid-trial.d": "Eine Formulierung zu unbezahlter Probearbeit kommt vor. Prüfen Sie den Zusammenhang; ein Treffer allein belegt weder die vereinbarten Bedingungen noch die Rechtmäßigkeit.",
  "ra.w.unpaid-trial.r": "Fragen Sie, ob produktive Probearbeit verlangt wird und wie sie vergütet würde.",
  "ra.w.upfront-fee.t": "Formulierung zu Gebühr oder Kaution prüfen",
  "ra.w.upfront-fee.d": "Gebühren- oder Kautionssprache kommt vor. Diese Regel entscheidet nicht, ob eine Zahlung verlangt wird oder das Unternehmen seriös ist.",
  "ra.w.upfront-fee.r": "Klären Sie Betrag, Zweck, Empfänger und Rückerstattungsbedingungen, bevor Sie entscheiden.",
  "ra.w.document-retention.t": "Formulierung zur Dokumentenverwahrung prüfen",
  "ra.w.document-retention.d": "Sprache zur Dokumentenverwahrung kommt vor. Prüfen Sie den Umgebungstext, um zu sehen, ob es eine Pflicht, ein Verbot oder ein Beispiel ist.",
  "ra.w.document-retention.r": "Fragen Sie, ob Originale abgegeben werden müssen, wie lange und ob Kopien genügen.",
  "ra.w.unpaid-overtime.t": "Formulierung zur Überstundenvergütung prüfen",
  "ra.w.unpaid-overtime.d": "Eine Formulierung zu unvergüteten Überstunden kommt vor. Bestätigen Sie den gesamten Zusammenhang, bevor Sie sie als Verpflichtung auslegen.",
  "ra.w.unpaid-overtime.r": "Fordern Sie Überstunden, Genehmigungsregeln und Ausgleichsbedingungen schriftlich an.",
  "ra.w.scam-gift-card-crypto.t": "Ungewöhnliche Zahlungsmethode erwähnt",
  "ra.w.scam-gift-card-crypto.d": "Geschenkkarten, Kryptowährung oder Geldtransferdienste sind ein verbreiteter Weg, Bewerbern Geld abzunehmen. Seriöse Arbeitgeber zahlen Löhne normalerweise auf ein Bankkonto und verlangen von Bewerbern keine solche Zahlung.",
  "ra.w.scam-gift-card-crypto.r": "Senden Sie kein Geld und keine Kartencodes. Fragen Sie den Zahlungszweck schriftlich ab und prüfen Sie das Unternehmen über einen unabhängigen Kanal.",
  "ra.w.scam-pay-to-start.t": "Zahlung vor Arbeitsbeginn oder Vertrag verlangt",
  "ra.w.scam-pay-to-start.d": "Die Formulierung verlangt Geld, bevor die Arbeit beginnt oder ein Vertrag ausgestellt wird.",
  "ra.w.scam-pay-to-start.r": "Fragen Sie vor jeder Zahlung schriftlich, wer das Geld erhält, warum und ob es erstattbar ist.",
  "ra.w.scam-guaranteed-abroad.t": "Zugesicherte Stelle oder Visum",
  "ra.w.scam-guaranteed-abroad.d": "Kein Vermittler kann eine Stelle im Ausland, ein Visum oder eine Arbeitserlaubnis rechtmäßig garantieren. Garantien in Verbindung mit Gebühren sind ein anerkanntes Warnzeichen.",
  "ra.w.scam-guaranteed-abroad.r": "Prüfen Sie die Lizenz der Agentur bei der Auslandsbeschäftigungs-Aufsicht Ihrer Regierung und beim Arbeitgeber direkt.",
  "ra.w.scam-off-platform-chat.t": "Einstellung nur über eine Chat-App",
  "ra.w.scam-off-platform-chat.d": "Das Angebot verlagert das Gespräch in eine private Chat-App. Echte Recruiter nutzen diese Apps oft auch, das allein beweist also nichts, entfernt aber Nachweise und Firmenprüfungen.",
  "ra.w.scam-off-platform-chat.r": "Verlangen Sie vor dem Teilen von Dokumenten eine E-Mail von der eigenen Domain des Unternehmens und einen Vertrag.",
  "ra.w.scam-sensitive-data-early.t": "Sensible Zugangsdaten oder Codes verlangt",
  "ra.w.scam-sensitive-data-early.d": "Bank-Logins, PINs und Einmalcodes werden für eine Einstellung nie benötigt.",
  "ra.w.scam-sensitive-data-early.r": "Geben Sie sie niemandem weiter. Wenden Sie sich an Ihre Bank, falls Sie es schon getan haben.",
  "ra.w.scam-urgency.t": "Druck, sofort zu handeln",
  "ra.w.scam-urgency.d": "Eine sehr kurze Frist lässt keine Zeit, den Arbeitgeber zu prüfen.",
  "ra.w.scam-urgency.r": "Nehmen Sie sich Zeit, das Unternehmen zu prüfen; echte Angebote können eine angemessene Zeit warten.",
  "ra.w.scam-unrealistic-pay.t": "Sehr hohe Bezahlung ohne Erfahrung",
  "ra.w.scam-unrealistic-pay.d": "Hohe Tages- oder Wochenbezahlung ohne Erfahrung oder Qualifikation ist ein verbreiteter Köder.",
  "ra.w.scam-unrealistic-pay.r": "Vergleichen Sie mit der üblichen Bezahlung für die Rolle und fragen Sie genau, welche Arbeit geleistet wird und wer zahlt.",
  "ra.w.scam-free-mail-company.t": "Eine Firmenrolle mit kostenloser E-Mail-Adresse",
  "ra.w.scam-free-mail-company.d": "Der Kontakt nutzt einen kostenlosen E-Mail-Dienst, obwohl die Nachricht für ein Unternehmen spricht. Kleine Arbeitgeber und einzelne Recruiter tun das legitim, daher ist es ein Anlass zur Prüfung, kein Befund.",
  "ra.w.scam-free-mail-company.r": "Fragen Sie nach einer Adresse auf der eigenen Domain des Unternehmens und bestätigen Sie das Unternehmen dann unabhängig.",
  "ra.q.q-pay-date": "An welchem Tag jedes Monats wird das Gehalt überwiesen oder ausgezahlt?",
  "ra.q.q-overtime": "Wenn die Arbeit die vereinbarten Wochenstunden überschreitet, wie hoch ist der Überstundensatz?",
  "ra.q.q-equipment": "Stellt das Unternehmen notwendige Arbeitsmittel, Schutzausrüstung oder Uniformen bereit?",
