  "ai.unavailable": "Live-KI ist nicht verfügbar, bis der Betreiber einen Anbieter einrichtet und dessen Datenverarbeitungsrichtlinie genehmigt. Es wurde kein Angebotstext gesendet. Nutzen Sie oben „Bedingungen vorschlagen“ mit lokalen Regeln für eine lokale Prüfung; das ist keine KI.",
