  "ai.sendIntro": "Senden Sie den geprüften Text unten zur beratenden Analyse an {provider} ({model}). Entfernen Sie zuvor Namen, Kontaktdaten, Kennnummern und vertrauliche Bedingungen.",
  "ai.redactNote": "Die automatische Schwärzung entfernt einige erkennbare Kennungen. Sie kann Anonymität nicht garantieren. Prüfen Sie die gesamte Vorschau, bevor Sie einwilligen.",
